import numpy as np
from scipy.optimize import curve_fit
cv=lambda s:float(s.replace(',','.'))
raw,y=np.loadtxt('graphene.dat',delimiter='\t',converters={0:cv,1:cv}).T
x=1e7/raw

def lor(x,x0,gamma,amplitude,offset):
    return offset+amplitude*gamma**2/((x-x0)**2+gamma**2)

def fit(center,half):
    m=(x>center-half)&(x<center+half)
    xx,yy=x[m],y[m]
    edge=np.r_[yy[:max(3,len(yy)//10)],yy[-max(3,len(yy)//10):]]
    off=np.median(edge); amp=yy.max()-off; x0=xx[np.argmax(yy)]
