const r = await tools.exec_command({"cmd":"python - <<'PY'
import json
import numpy as np
from scipy.optimize import curve_fit

convert = lambda value: float(value.replace(',', '.'))
raw_x, intensity = np.loadtxt(
    'graphene.dat', delimiter='\t', converters={0: convert, 1: convert}
).T
shift = 1e7 / raw_x

def lorentzian(x, x0, gamma, amplitude, offset):
    return offset + amplitude * gamma**2 / ((x - x0)**2 + gamma**2)

windows = {'G': (1500.0, 1650.0), '2D': (2600.0, 2800.0)}
with open('results.json') as handle:
    saved = json.load(handle)

for peak, (low, high) in windows.items():
    selected = (shift >= low) & (shift <= high)
    x, y = shift[selected], intensity[selected]
    peak_i = int(np.argmax(y))
    initial_offset = float(np.median(np.r_[y[:5], y[-5:]]))
    fitted, _ = curve_fit(
        lorentzian, x, y,
        p0=(x[peak_i], 15.0, y[peak_i] - initial_offset, initial_offset),
        maxfev=100000,
    )
    written = np.array([saved[peak][key] for key in ('x0', 'gamma', 'amplitude', 'offset')])
    rmse = float(np.sqrt(np.mean((y - lorentzian(x, *written))**2)))
    print(peak, 'max_saved_fit_delta=', float(np.max(np.abs(written-fitted))), 'rmse=', rmse, 'points=', len(x))
